export interface ConnectorConfig {
  airtableApiKey: string;
  baseId: string;
  tableName: string;
  recordId?: string;
  fetch?: typeof fetch;
}

export interface JotformInput {
  email: string;
  name?: string;
  phone?: string;
  address?: string;
  rawRequest?: string;
}

export interface ConnectorResult {
  recordId: string;
  updatedFields: string[];
  airtableResponse: {
    id: string;
    fields: Record<string, unknown>;
  };
}

function isEmpty(value: unknown): boolean {
  return value === undefined || value === null || value === '';
}

async function parsePayload(payload: JotformInput): Promise<JotformInput> {
  if (payload.rawRequest) {
    try {
      const parsed = JSON.parse(payload.rawRequest);
      return parsed as JotformInput;
    } catch {
      // fall through to use payload as-is
    }
  }
  return payload;
}

export async function handle(payload: JotformInput, config: ConnectorConfig): Promise<ConnectorResult> {
  const fetchImpl = config.fetch ?? globalThis.fetch;
  if (!fetchImpl) {
    throw new Error('fetch implementation not available');
  }

  const parsed = await parsePayload(payload);

  if (!parsed.email || isEmpty(parsed.email)) {
    throw new Error('Missing required field: email');
  }

  const { airtableApiKey, baseId, tableName, recordId: configRecordId } = config;
  const email = parsed.email;

  let recordId = configRecordId;
  let airtableFields: Record<string, unknown> = {};

  if (!recordId) {
    const filterFormula = `{email}='${email}'`;
    const url = `https://api.airtable.com/v0/${baseId}/${tableName}?filterByFormula=${encodeURIComponent(filterFormula)}`;

    const response = await fetchImpl(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${airtableApiKey}`,
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      throw new Error(`Airtable lookup failed: ${response.status} ${response.statusText} at GET ${url}`);
    }

    const data = (await response.json()) as {
      records: Array<{ id: string; fields: Record<string, unknown> }>;
    };

    if (!data.records || data.records.length === 0) {
      throw new Error(`No Airtable record found for email: ${email}`);
    }

    recordId = data.records[0].id;
    airtableFields = data.records[0].fields || {};
  }

  if (!recordId) {
    throw new Error('Could not determine Airtable record ID');
  }

  const jotformFields = {
    name: parsed.name,
    phone: parsed.phone,
    address: parsed.address,
  };

  const fieldsToUpdate: Record<string, string> = {};
  const updatedFields: string[] = [];

  for (const [fieldName, jotformValue] of Object.entries(jotformFields)) {
    if (isEmpty(jotformValue)) continue;

    const airtableValue = airtableFields[fieldName];
    const shouldUpdate = configRecordId ? true : isEmpty(airtableValue);

    if (shouldUpdate) {
      fieldsToUpdate[fieldName] = String(jotformValue);
      updatedFields.push(fieldName);
    }
  }

  if (updatedFields.length === 0) {
    return {
      recordId,
      updatedFields: [],
      airtableResponse: { id: recordId, fields: airtableFields },
    };
  }

  const patchUrl = `https://api.airtable.com/v0/${baseId}/${tableName}/${recordId}`;
  const patchBody = { fields: fieldsToUpdate };

  const patchResponse = await fetchImpl(patchUrl, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${airtableApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(patchBody),
  });

  if (!patchResponse.ok) {
    throw new Error(`Airtable PATCH failed: ${patchResponse.status} ${patchResponse.statusText} at PATCH ${patchUrl}`);
  }

  const patchData = (await patchResponse.json()) as { id: string; fields: Record<string, unknown> };

  return {
    recordId: patchData.id,
    updatedFields,
    airtableResponse: patchData,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, JotformInput } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      airtableApiKey: 'test-api-key',
      baseId: 'appXXXXXXXXXXXX',
      tableName: 'Table%201',
      recordId: 'recXXXXXXXXXXXX',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformInput, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(calls[0].method).toBe('PATCH');
    expect(calls[0].json).toEqual({
      fields: {
        name: 'John Doe',
        phone: '555-1234',
        address: '123 Main St',
      },
    });
    expect(result.recordId).toBe('recXXXXXXXXXXXX');
    expect(result.updatedFields).toEqual(['name', 'phone', 'address']);
  });
});

describe('handle', () => {
  it('looks up record by email and patches only empty fields', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse({
          records: [{ id: 'rec123', fields: { name: '', phone: 'existing', address: '' } }],
        });
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec123')) {
        return jsonResponse({
          id: 'rec123',
          fields: { name: 'John', phone: 'existing', address: '123 St' },
        });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      fetch,
    };

    const payload: JotformInput = {
      email: 'test@example.com',
      name: 'John',
      phone: '555-1234',
      address: '123 St',
    };

    const result = await handle(payload, config);

    expect(calls.length).toBe(2);
    expect(calls[0].method).toBe('GET');
    expect(calls[0].url).toContain('filterByFormula');
    expect(calls[1].method).toBe('PATCH');
    expect(calls[1].json).toEqual({
      fields: { name: 'John', address: '123 St' },
    });
    expect(result.updatedFields).toEqual(['name', 'address']);
  });

  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      fetch,
    };
    const payload = { name: 'John' } as JotformInput;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('throws on non-2xx lookup response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      fetch,
    };
    const payload: JotformInput = { email: 'test@example.com' };
    await expect(handle(payload, config)).rejects.toThrow('Airtable lookup failed: 401 Unauthorized at GET');
    expect(calls[0].method).toBe('GET');
  });

  it('throws on non-2xx patch response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'rec1', fields: {} }] });
      }
      return jsonResponse({ error: 'Forbidden' }, 403);
    });
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      fetch,
    };
    const payload: JotformInput = { email: 'test@example.com', name: 'John' };
    await expect(handle(payload, config)).rejects.toThrow('Airtable PATCH failed: 403 Forbidden at PATCH');
    expect(calls.length).toBe(2);
  });

  it('handles rawRequest payload', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'rec1', fields: {} }] });
      }
      return jsonResponse({ id: 'rec1', fields: { name: 'John' } }, 200);
    });
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      fetch,
    };
    const payload: JotformInput = {
      rawRequest: JSON.stringify({ email: 'test@example.com', name: 'John' }),
    };
    const result = await handle(payload, config);
    expect(result.updatedFields).toContain('name');
  });

  it('returns early when no fields to update', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'rec1', fields: { name: 'Existing' } }] });
      }
      return jsonResponse({}, 200);
    });
    const config: ConnectorConfig = {
      airtableApiKey: 'key',
      baseId: 'appBase',
      tableName: 'Table',
      fetch,
    };
    const payload: JotformInput = { email: 'test@example.com', name: '' };
    const result = await handle(payload, config);
    expect(calls.length).toBe(1);
    expect(result.updatedFields).toEqual([]);
  });
});

# Jotform to Airtable Connector

This connector processes Jotform form submissions and updates corresponding Airtable records by patching only the fields that are empty.

## What it does

1. Receives a Jotform webhook payload (either parsed JSON or raw multipart/form-data with a `rawRequest` field)
2. Extracts `email`, `name`, `phone`, and `address` from the submission
3. Looks up the Airtable record by email using `filterByFormula` (unless `recordId` is provided in config)
4. Fetches the current record to determine which fields are empty
5. PATCHes only the fields that are empty in Airtable and have non-empty values in the Jotform submission
6. Returns the updated record ID and list of updated fields

## Configuration

The connector requires the following configuration (typically from environment variables):

| Config Property | Environment Variable | Description |
|----------------|---------------------|-------------|
| `airtableApiKey` | `AIRTABLE_API_KEY` | Airtable Personal Access Token (Bearer token) |
| `baseId` | `AIRTABLE_BASE_ID` | Airtable Base ID (e.g., `appXXXXXXXXXXXX`) |
| `tableName` | `AIRTABLE_TABLE_NAME` | Airtable Table Name (URL-encoded, e.g., `Table%201`) |
| `recordId` | `AIRTABLE_RECORD_ID` | *Optional* Airtable Record ID. If provided, skips the email lookup. |

## Usage Example

```typescript
import { handle, ConnectorConfig, JotformInput } from './connector';

const config: ConnectorConfig = {
  airtableApiKey: process.env.AIRTABLE_API_KEY!,
  baseId: process.env.AIRTABLE_BASE_ID!,
  tableName: process.env.AIRTABLE_TABLE_NAME!,
  // recordId: process.env.AIRTABLE_RECORD_ID, // optional
};

// Jotform webhook handler
app.post('/jotform-webhook', async (req, res) => {
  try {
    // req.body may contain rawRequest (multipart) or direct fields
    const payload: JotformInput = req.body;
    const result = await handle(payload, config);
    res.json({ success: true, ...result });
  } catch (error) {
    console.error(error);
    res.status(500).json({ success: false, error: error.message });
  }
});
```

## Assumptions

- The Jotform submission contains an `email` field that uniquely identifies the Airtable record.
- The Airtable table has columns named exactly `name`, `phone`, and `address` that may be empty and need updating.
- The integration filters out null/empty values from the Jotform payload before PATCHing so only truly empty Airtable fields are updated (when `recordId` is not provided in config, the connector checks current field values).
- Jotform webhooks send submission data as multipart/form-data with a `rawRequest` field containing the JSON string of form fields. The connector parses this automatically.
- Airtable API requires a Bearer token in the Authorization header.
- The Airtable `filterByFormula` uses the field name `email` (lowercase) to match records.

## API Details

### Source: Jotform Webhook
- **Method**: POST (webhook delivery)
- **Payload**: multipart/form-data with `rawRequest` field (JSON string) or direct JSON fields
- **Auth**: None

### Target: Airtable
- **Lookup**: GET `https://api.airtable.com/v0/{baseId}/{tableName}?filterByFormula={email}='{email}'`
- **Update**: PATCH `https://api.airtable.com/v0/{baseId}/{tableName}/{recordId}`
- **Auth**: Bearer token (`AIRTABLE_API_KEY`)
- **Body**: `{ "fields": { "name": "...", "phone": "...", "address": "..." } }` (only non-empty fields for empty Airtable columns)

